-- AlterTable
ALTER TABLE "User" ADD COLUMN "reservasVistasEn" TIMESTAMP(3);

-- CreateTable
CREATE TABLE "VehicleModelCatalog" (
    "id" TEXT NOT NULL,
    "marca" TEXT NOT NULL,
    "modelo" TEXT NOT NULL,
    "tipo" "VehicleType" NOT NULL,
    "marcaNormalizada" TEXT NOT NULL,
    "modeloNormalizado" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "VehicleModelCatalog_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "VehicleModelCatalog_marcaNormalizada_idx" ON "VehicleModelCatalog"("marcaNormalizada");

